function formatDate(dateString) {
    // Remove "Am", "um", and time (like "06:36")
    let formattedDate = dateString.replace(/^(Am\s)?(\d{1,2}\.\s[a-zA-ZäöüÄÖÜ]+\s\d{4})(\sum\s\d{2}:\d{2})?$/, '$2');
    
    return formattedDate;
}

function displayActivities(activities, listName, h1Name, clearName) {
    const h1 = document.getElementById(h1Name);
    let endDate = formatDate(activities[0].date);
    let startDate = formatDate(activities[activities.length - 1].date);
    h1.textContent = `${clearName} Aktivitäten - ${activities.length} (${startDate} - ${endDate})`;
    const activityList = document.getElementById(listName);
    activityList.innerHTML = '';

    activities.forEach(activity => {
        const activityItem = document.createElement('div');
        activityItem.classList.add('activity-item');

        // Create the activity title (collapsible)
        const activityTitle = document.createElement('h2');
        activityTitle.textContent = activity.activity;
        activityTitle.addEventListener('click', () => {
            const content = activityItem.querySelector('.collapsible');
            content.style.display = content.style.display === 'block' ? 'none' : 'block';
        });

        const date = document.createElement('p');
        date.textContent = `${activity.date}`;

        let infos;

        if (activity.km) {
          infos = document.createElement('p');
          infos.textContent = `${activity.km} KM - ${activity.hm} HM`;
        }

        // Create the link
        const link = document.createElement('p');
        const hyperlink = document.createElement('a');
        hyperlink.href = activity.link;
        hyperlink.textContent = 'Aktivität';
        hyperlink.target = '_blank';
        link.appendChild(hyperlink);

        const description = document.createElement('p');
        description.textContent = `${activity.description}`;

        let buddies;

        if (activity.buddies.length > 0) {
          buddies = document.createElement('p');
          buddies.classList.add(['buddies'])
          buddies.style = 'color: red;'
          buddies.textContent = `Buddies: ${activity.buddies.join(', ')}`;
        } 

        // const copyButton = document.createElement('button');
        // copyButton.classList.add('copy-button');
        // copyButton.textContent = 'Copy Description';
        // copyButton.addEventListener('click', () => {
        //     copyToClipboard(activity.description);
        // });

        // Collapsible section for description
        // const collapsibleContent = document.createElement('div');
        // collapsibleContent.classList.add('collapsible');
        // collapsibleContent.appendChild(description);
        // collapsibleContent.appendChild(copyButton);

        activityItem.appendChild(activityTitle);
        activityItem.appendChild(date);

        if (infos) {
          activityItem.appendChild(infos);
        }

        if (buddies) {
          activityItem.appendChild(buddies);
        }
        
        activityItem.appendChild(link);
        activityItem.appendChild(description);

        activityList.appendChild(activityItem);
    });
}

function copyToClipboard(text) {
    navigator.clipboard.writeText(text).then(() => {
        alert('Description copied to clipboard!');
    }).catch(err => {
        console.error('Failed to copy text: ', err);
    });
}

function openFahrer(evt, fahrer) {
  var i, tabcontent, tablinks;
  tabcontent = document.getElementsByClassName("container");
  for (i = 0; i < tabcontent.length; i++) {
    tabcontent[i].style.display = "none";
  }
  tablinks = document.getElementsByClassName("tablinks");
  for (i = 0; i < tablinks.length; i++) {
    tablinks[i].className = tablinks[i].className.replace(" active", "");
  }

  if (fahrer === 'Dinkels') {
    currentList = 'activity-list-dinkels';
    displayActivities(activitiesDinkels, 'activity-list-dinkels', 'h1-dinkels', 'Dinkels');
  } else if (fahrer === 'Niki') {
    currentList = 'activity-list-niki';
    displayActivities(activitiesNiki, 'activity-list-niki', 'h1-niki', 'Niki');
  } else if (fahrer === 'Julian') {
    currentList = 'activity-list-julian';
    displayActivities(activitiesJulian, 'activity-list-julian', 'h1-julian', 'Julian');
  } else if (fahrer === 'Martin') {
    currentList = 'activity-list-martin';
    displayActivities(activitiesMartin, 'activity-list-martin', 'h1-martin', 'Martin');
  } else if (fahrer === 'Maxi') {
    currentList = 'activity-list-maxi';
    displayActivities(activitiesMaxi, 'activity-list-maxi', 'h1-maxi', 'Maxi');
  }

  document.getElementById(fahrer).style.display = "block";
  evt.currentTarget.className += " active";
}

let currentList = 'activity-list-dinkels';
let withBuddies = false;

displayActivities(activitiesDinkels, 'activity-list-dinkels', 'h1-dinkels', 'Dinkels');

document.getElementById('toggleButton-buddies-dinkels').addEventListener('click', function() {
    const activityList = document.getElementById(currentList);
    withBuddies = !withBuddies;

    if (withBuddies) {
      var button = document.getElementById('toggleButton-buddies-dinkels');
      button.textContent = "Alle";
      displayActivities(activitiesDinkels.filter(entry => entry.buddies.length > 0), 'activity-list-dinkels', 'h1-dinkels', 'Dinkels');
    } else {
      var button = document.getElementById('toggleButton-buddies-dinkels');
      button.textContent = "Mit Buddies";
      displayActivities(activitiesDinkels, 'activity-list-dinkels', 'h1-dinkels', 'Dinkels');
    }
});

